// static
mozilla::pkix::Result nsCMSSecureMessage::VerifyEmailUsageLocalOnly(
    CertVerifier* aCertVerifier, const nsTArray<uint8_t>& aCertDER,
    mozilla::psm::VerifyUsage aUsage) {
  // FLAG_LOCAL_ONLY skips OCSP so this stays on the main thread; only valid
  // because callers pass the user's own configured cert.
  nsTArray<nsTArray<uint8_t>> unusedChain;
  return aCertVerifier->VerifyCert(aCertDER, aUsage, mozilla::pkix::Now(),
                                   nullptr, nullptr, unusedChain,
                                   CertVerifier::FLAG_LOCAL_ONLY);
}

nsresult nsCMSSecureMessage::CheckUsageOk(nsIX509Cert* aCert,
                                          SECCertificateUsage aUsage,
                                          bool* aCanBeUsed) {
  NS_ENSURE_ARG_POINTER(aCert);
  *aCanBeUsed = false;

  nsTArray<uint8_t> certBytes;
  nsresult rv = aCert->GetRawDER(certBytes);
  NS_ENSURE_SUCCESS(rv, rv);

  RefPtr<SharedCertVerifier> certVerifier(GetDefaultCertVerifier());
  NS_ENSURE_TRUE(certVerifier, NS_ERROR_UNEXPECTED);

  mozilla::psm::VerifyUsage usageForPkix;
  switch (aUsage) {
    case certificateUsageEmailSigner:
      usageForPkix = mozilla::psm::VerifyUsage::EmailSigner;
      break;
    case certificateUsageEmailRecipient:
      usageForPkix = mozilla::psm::VerifyUsage::EmailRecipient;
      break;
    default:
      return NS_ERROR_UNEXPECTED;
  }

  *aCanBeUsed =
      VerifyEmailUsageLocalOnly(certVerifier, certBytes, usageForPkix) ==
      mozilla::pkix::Success;
  return NS_OK;
}

NS_IMETHODIMP nsCMSSecureMessage::CanBeUsedForEmailEncryption(
    nsIX509Cert* aCert, bool* aCanBeUsed) {
  return CheckUsageOk(aCert, certificateUsageEmailRecipient, aCanBeUsed);
}

NS_IMETHODIMP nsCMSSecureMessage::CanBeUsedForEmailSigning(nsIX509Cert* aCert,
                                                           bool* aCanBeUsed) {
  return CheckUsageOk(aCert, certificateUsageEmailSigner, aCanBeUsed);
}
